<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';import { CheckCircle2, Download, FilePlus2, RefreshCw, Send } from 'lucide-vue-next';import { ElMessage } from 'element-plus';import { api } from '../api';import AnalyticsChart from '../components/AnalyticsChart.vue';import PageHeader from '../components/PageHeader.vue';import type { AnalyticsOptions, PageData, RegulatoryReport } from '../types';
const loading=ref(false),items=ref<RegulatoryReport[]>([]),total=ref(0),options=reactive<AnalyticsOptions>({enterprises:[],organizations:[],vehicles:[],accidents:[]}),dialog=ref(false),drawer=ref(false),detail=ref<RegulatoryReport|null>(null),query=reactive({q:'',type:'',status:''});const form=reactive({title:'',reportType:'MONTHLY',category:'COMPREHENSIVE',dates:[] as string[],enterpriseId:'',recipient:''});const typeText=(v:string)=>({DAILY:'日报',WEEKLY:'周报',MONTHLY:'月报',SPECIAL:'专题报',OPERATIONS:'运行分析',SAFETY:'安全态势',COMPREHENSIVE:'综合监管',ENTERPRISE:'企业专项'} as any)[v]??v;const statusText=(v:string)=>v==='DISTRIBUTED'?'已分发':'已生成';
const summaryOption=computed(()=>{const ops=(detail.value?.summary as any)?.operations?.kpis,safe=(detail.value?.summary as any)?.safety?.kpis;return{xAxis:{type:'category',data:['运行车辆','运行次数','告警','事故','违规'],axisLabel:{fontSize:10}},yAxis:{type:'value',splitLine:{lineStyle:{color:'#edf0f2'}}},grid:{left:42,right:16,top:18,bottom:32},series:[{type:'bar',barMaxWidth:28,data:[ops?.vehicles??0,ops?.trips??0,safe?.alerts??0,safe?.accidents??0,safe?.violations??0],itemStyle:{color:(p:any)=>['#315f91','#527da5','#d97706','#b91c1c','#6b7280'][p.dataIndex],borderRadius:[4,4,0,0]}}]}});
async function load(){loading.value=true;try{const p=new URLSearchParams({page:'1',pageSize:'50'});if(query.q)p.set('q',query.q);if(query.type)p.set('type',query.type);if(query.status)p.set('status',query.status);const r=await api<PageData<RegulatoryReport>>(`/analytics/reports?${p}`);items.value=r.items;total.value=r.total}catch(e){ElMessage.error(e instanceof Error?e.message:'报表加载失败')}finally{loading.value=false}}async function create(){await api('/analytics/reports',{method:'POST',body:JSON.stringify({title:form.title,reportType:form.reportType,category:form.category,periodStart:form.dates[0],periodEnd:form.dates[1],enterpriseId:form.enterpriseId||undefined,recipient:form.recipient||undefined})});ElMessage.success('监管报表已生成');dialog.value=false;await load()}async function open(row:RegulatoryReport){detail.value=await api<RegulatoryReport>(`/analytics/reports/${row.id}`);drawer.value=true}async function distribute(row:RegulatoryReport){await api(`/analytics/reports/${row.id}`,{method:'PATCH',body:JSON.stringify({status:'DISTRIBUTED',recipient:row.recipient||'相关监管机构'})});ElMessage.success('报表已标记分发');await load()}async function download(row:RegulatoryReport){const file=await api<{filename:string;mimeType:string;content:string}>(`/analytics/reports/${row.id}/export`);const url=URL.createObjectURL(new Blob([file.content],{type:file.mimeType}));const a=document.createElement('a');a.href=url;a.download=file.filename;a.click();URL.revokeObjectURL(url)}onMounted(async()=>{Object.assign(options,await api<AnalyticsOptions>('/analytics/options'));await load()});
</script>
<template><PageHeader title="监管报表" :count="total" description="统一统计口径，按日、周、月及专题周期生成、在线查看、导出与分发报表。"><el-button type="primary" :icon="FilePlus2" @click="dialog=true">生成报表</el-button><el-button :icon="RefreshCw" :loading="loading" @click="load">刷新</el-button></PageHeader><section class="phase6-filter"><el-input v-model="query.q" clearable placeholder="报表编号或名称" style="width:240px" @keyup.enter="load"/><el-select v-model="query.type" clearable placeholder="报表分类" style="width:150px"><el-option label="运行分析" value="OPERATIONS"/><el-option label="安全态势" value="SAFETY"/><el-option label="综合监管" value="COMPREHENSIVE"/><el-option label="企业专项" value="ENTERPRISE"/></el-select><el-select v-model="query.status" clearable placeholder="分发状态" style="width:130px"><el-option label="已生成" value="GENERATED"/><el-option label="已分发" value="DISTRIBUTED"/></el-select><el-button type="primary" @click="load">查询</el-button></section><section class="phase6-panel" v-loading="loading"><el-table :data="items" empty-text="暂无监管报表"><el-table-column label="报表" min-width="300"><template #default="{row}"><div class="identity-cell"><strong>{{row.title}}</strong><span>{{row.businessNo}}</span></div></template></el-table-column><el-table-column label="周期" width="190"><template #default="{row}">{{row.periodStart.slice(0,10)}} 至 {{row.periodEnd.slice(0,10)}}</template></el-table-column><el-table-column label="类型" width="130"><template #default="{row}">{{typeText(row.reportType)}} · {{typeText(row.category)}}</template></el-table-column><el-table-column label="生成机构" prop="organization.name" min-width="170"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='DISTRIBUTED'?'success':'info'">{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column label="操作" width="220"><template #default="{row}"><el-button link type="primary" @click="open(row)">查看</el-button><el-button link :icon="Download" @click="download(row)">导出</el-button><el-button v-if="row.status!=='DISTRIBUTED'" link :icon="Send" @click="distribute(row)">分发</el-button></template></el-table-column></el-table></section><el-dialog v-model="dialog" title="生成监管报表" width="620px"><el-form label-position="top"><el-form-item label="报表名称"><el-input v-model="form.title" placeholder="例如：2026 年 9 月无人快递车监管月报"/></el-form-item><div class="form-grid"><el-form-item label="周期类型"><el-select v-model="form.reportType"><el-option label="日报" value="DAILY"/><el-option label="周报" value="WEEKLY"/><el-option label="月报" value="MONTHLY"/><el-option label="专题报" value="SPECIAL"/></el-select></el-form-item><el-form-item label="报表分类"><el-select v-model="form.category"><el-option label="综合监管" value="COMPREHENSIVE"/><el-option label="运行分析" value="OPERATIONS"/><el-option label="安全态势" value="SAFETY"/><el-option label="企业专项" value="ENTERPRISE"/></el-select></el-form-item></div><el-form-item label="统计周期"><el-date-picker v-model="form.dates" type="daterange" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item><el-form-item label="指定企业（可选）"><el-select v-model="form.enterpriseId" clearable filterable><el-option v-for="x in options.enterprises" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="分发对象"><el-input v-model="form.recipient" placeholder="相关处室、区县机构或企业联系人"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :icon="CheckCircle2" @click="create">生成报表</el-button></template></el-dialog><el-drawer v-model="drawer" title="监管报表预览" size="720px"><template v-if="detail"><div class="report-preview-head"><span>{{typeText(detail.reportType)}} · {{typeText(detail.category)}}</span><h2>{{detail.title}}</h2><p>{{detail.businessNo}} · {{detail.organization.name}} · {{detail.generatedByName}} 生成</p></div><AnalyticsChart :option="summaryOption" height="280px"/><div class="report-kpi-grid"><template v-if="(detail.summary as any)?.operations?.kpis"><span><small>运行车辆</small><b>{{(detail.summary as any).operations.kpis.vehicles}}</b></span><span><small>运行次数</small><b>{{(detail.summary as any).operations.kpis.trips}}</b></span><span><small>运行里程</small><b>{{(detail.summary as any).operations.kpis.mileage}} km</b></span><span><small>自主运行率</small><b>{{(detail.summary as any).operations.kpis.autonomousRate}}%</b></span></template><template v-if="(detail.summary as any)?.safety?.kpis"><span><small>安全告警</small><b>{{(detail.summary as any).safety.kpis.alerts}}</b></span><span><small>事故</small><b>{{(detail.summary as any).safety.kpis.accidents}}</b></span><span><small>违规</small><b>{{(detail.summary as any).safety.kpis.violations}}</b></span><span><small>闭环率</small><b>{{(detail.summary as any).safety.kpis.closureRate}}%</b></span></template></div><div class="report-actions"><el-button :icon="Download" @click="download(detail)">导出 CSV</el-button><el-button v-if="detail.status!=='DISTRIBUTED'" type="primary" :icon="Send" @click="distribute(detail)">分发报表</el-button></div></template></el-drawer></template>
